function fastingBreadcrumb(items=[]){return `<nav class="module-breadcrumb" aria-label="Breadcrumb"><a href="/home" data-route>App Home</a><i class="ph ph-caret-right"></i><a href="/fasting" data-route>Fasting Companion</a>${items.map((item,index)=>`${index===items.length-1||!item.route?`<i class="ph ph-caret-right"></i><span>${esc(item.label)}</span>`:`<i class="ph ph-caret-right"></i><a href="${item.route}" data-route>${esc(item.label)}</a>`}`).join('')}</nav>`}
function fastingEpigraph(){return pageEpigraph({quote:'“Fasting is for Me, and I shall reward for it.”',citation:'Sahih al-Bukhari and Sahih Muslim — full sourced study note reserved for the content phase'})}
function fastingCard(route,title,description,iconName='book-open-text'){return `<a class="fasting-card" href="${route}" data-route><span class="fasting-card-icon"><i class="ph ph-${iconName}"></i></span><span><strong>${esc(title)}</strong><small>${esc(description)}</small></span><i class="ph ph-arrow-right"></i></a>`}
function fastingRecords(){let shared=[];try{shared=JSON.parse(localStorage.getItem('ummiby.fasting.records')||'[]')}catch{}let ramadan=[];try{const raw=JSON.parse(localStorage.getItem('ummiby.ramadan.fastingRecords')||'[]');ramadan=Array.isArray(raw)?raw:[]}catch{}return [...shared,...ramadan.map(x=>({...x,fastType:x.fastType||'Ramadan',sourceModule:'ramadan'}))].filter(x=>x&&x.date).sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
function fastingStats(){const records=fastingRecords(),completed=records.filter(x=>x.status==='completed'||x.status==='fasted'||x.completed===true);return {records,completed,total:completed.length,ramadan:completed.filter(x=>String(x.fastType||'').toLowerCase()==='ramadan').length,sunnah:completed.filter(x=>!['ramadan','make-up','makeup'].includes(String(x.fastType||'').toLowerCase())).length,makeup:completed.filter(x=>String(x.fastType||'').toLowerCase().includes('make')).length}}
function fastingHome(){const stats=fastingStats();return `<section class="vision-page fasting-companion-page fasting-home">${fastingEpigraph()}<section class="fasting-today-card"><div><span class="fasting-card-icon is-large"><i class="ph ph-sun-horizon"></i></span><div><p class="section-eyebrow">Fasting today</p><h2>Can I Fast Today?</h2><p>The date-aware Sunnah fasting guide is prepared for a future calendar phase. This foundation already has a permanent home for timely guidance.</p></div></div><a class="button button-primary" href="/fasting/sunnah" data-route>Explore Sunnah Fasts</a></section><div class="fasting-dashboard-grid"><section><div class="section-heading"><div><p class="section-eyebrow">Begin here</p><h2>Your Fasting Companion</h2></div></div><div class="fasting-home-links">${fastingCard('/fasting/learn','Learn About Fasting','Foundations, conditions, nullifiers, exemptions, and practical guidance.','book-open-text')}${fastingCard('/fasting/sunnah','Sunnah Fasts','Mondays, Thursdays, White Days, Ashura, Arafah, Shawwal, and more.','calendar-heart')}${fastingCard('/fasting/history','Fasting History','One lifelong record that includes Ramadan without duplicating its data.','archive')}${fastingCard('/fasting/makeup','Make-up Fasts','See missed Ramadan days, completed make-ups, and what remains.','list-checks')}${fastingCard('/fasting/library','Fasting Library','A future library for trusted articles, audio, video, books, and references.','books')}${fastingCard('/fasting/settings','Settings','Future Hijri calendar, reminder, history, and display preferences.','sliders-horizontal')}</div></section><aside class="fasting-summary-panel"><header><div><p class="section-eyebrow">Your record</p><h2>Fasting at a Glance</h2></div><span class="status-pill">Unified history</span></header><div class="fasting-stat-list"><div><span>Lifetime fasts recorded</span><strong>${stats.total}</strong></div><div><span>Ramadan fasts</span><strong>${stats.ramadan}</strong></div><div><span>Sunnah fasts</span><strong>${stats.sunnah}</strong></div><div><span>Make-up fasts completed</span><strong>${stats.makeup}</strong></div></div><p><i class="ph ph-database"></i> Ramadan Central remains the owner of Ramadan records. Fasting Companion reads those records into this lifelong view.</p><a class="button button-secondary" href="/fasting/history" data-route>View Fasting History</a></aside></div><section class="fasting-ramadan-bridge"><span class="fasting-card-icon is-large"><i class="ph ph-moon"></i></span><div><p class="section-eyebrow">Connected companion</p><h2>Ramadan belongs in your lifelong fasting story</h2><p>Track each Ramadan day inside Ramadan Central. Completed fasts, missed days, reasons, and make-up progress can then appear throughout Fasting Companion without creating a second copy.</p></div><a class="button button-secondary" href="/ramadan/fasting" data-route>Open Ramadan Fasting</a></section></section>`}
function fastingLearn(){return `<section class="vision-page fasting-companion-page">${fastingBreadcrumb([{label:'Learn About Fasting'}])}${fastingEpigraph()}<header class="editorial-header"><p class="page-kicker">Guided learning</p><h2>Learn About Fasting</h2><p>A complete educational framework is ready for carefully sourced lessons about fasting as worship—not diet, fitness, or wellness tracking.</p></header><div class="fasting-topic-grid">${Object.entries(FASTING_LEARN).map(([id,x])=>fastingCard(`/fasting/learn/${id}`,x[0],x[1],x[2])).join('')}</div></section>`}
function fastingSunnah(){return `<section class="vision-page fasting-companion-page">${fastingBreadcrumb([{label:'Sunnah Fasts'}])}${fastingEpigraph()}<header class="editorial-header"><p class="page-kicker">Voluntary worship</p><h2>Sunnah Fasts</h2><p>Browse recurring and seasonal voluntary fasts. Future date-aware cards will surface what is relevant today and what is approaching.</p></header><div class="fasting-topic-grid">${Object.entries(SUNNAH_FASTS).map(([id,x])=>fastingCard(`/fasting/sunnah/${id}`,x[0],x[1],x[2])).join('')}</div></section>`}
function fastingHistory(){const s=fastingStats();const recent=s.records.slice(0,12);return `<section class="vision-page fasting-companion-page">${fastingBreadcrumb([{label:'Fasting History'}])}<header class="editorial-header"><p class="page-kicker">One lifelong record</p><h2>Fasting History</h2><p>Ramadan, Sunnah, and make-up fasts belong to one history even though each module keeps responsibility for its own records.</p></header><div class="fasting-history-summary"><article><i class="ph ph-calendar-check"></i><span>Completed fasts</span><strong>${s.total}</strong></article><article><i class="ph ph-moon"></i><span>Ramadan</span><strong>${s.ramadan}</strong></article><article><i class="ph ph-sparkle"></i><span>Sunnah</span><strong>${s.sunnah}</strong></article><article><i class="ph ph-list-checks"></i><span>Make-up</span><strong>${s.makeup}</strong></article></div><section class="fasting-history-shell"><div class="fasting-history-toolbar"><div class="filter-pills"><button class="is-active" type="button">All</button><button type="button">Ramadan</button><button type="button">Sunnah</button><button type="button">Make-up</button><button type="button">Missed</button></div><span class="status-pill">Calendar framework</span></div><div class="fasting-calendar-placeholder"><i class="ph ph-calendar-dots"></i><h3>Monthly and yearly history</h3><p>The unified history route and data boundary are established. Calendar, filters, insights, and year views can now be built without changing the architecture.</p></div>${recent.length?`<div class="fasting-record-list">${recent.map(x=>`<article><i class="ph ph-${x.sourceModule==='ramadan'?'moon':'check-circle'}"></i><span><strong>${esc(x.fastType||'Fast')}</strong><small>${new Date(x.date+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})} · ${esc(x.status||'recorded')}</small></span><em>${x.sourceModule==='ramadan'?'Ramadan Central':'Fasting Companion'}</em></article>`).join('')}</div>`:''}</section><aside class="fasting-data-note"><i class="ph ph-database"></i><div><strong>No duplicate Ramadan data</strong><p>Ramadan Central writes Ramadan entries. Fasting Companion reads them alongside year-round records and presents one continuous history.</p></div></aside></section>`}
function fastingMakeup(){return `<section class="vision-page fasting-companion-page">${fastingBreadcrumb([{label:'Make-up Fasts'}])}${fastingEpigraph()}<header class="editorial-header"><p class="page-kicker">Fulfill what remains</p><h2>Make-up Fasts</h2><p>A dedicated home for missed Ramadan days and completed make-up fasts, connected directly to the Ramadan record.</p></header><div class="fasting-makeup-grid"><article><span>Missed Ramadan days</span><strong>0</strong><small>Will be calculated from Ramadan Central</small></article><article><span>Make-ups completed</span><strong>0</strong><small>Recorded through Fasting Companion</small></article><article><span>Remaining</span><strong>0</strong><small>One shared calculation</small></article></div><div class="fasting-empty-panel"><i class="ph ph-list-checks"></i><h3>Your make-up plan will appear here</h3><p>Future entries can preserve the original missed date, reason, Ramadan year, completion date, and private notes.</p><button class="button button-primary" type="button" disabled>Add Make-up Fast</button><span>Entry controls are reserved for the tracking phase.</span></div></section>`}
function fastingLibrary(){return `<section class="vision-page fasting-companion-page">${fastingBreadcrumb([{label:'Fasting Library'}])}<header class="editorial-header"><p class="page-kicker">Trusted resources</p><h2>Fasting Library</h2><p>A structured resource shell for authentic articles, audio, video, books, and reference material.</p></header><div class="fasting-library-grid">${[['article','Articles'],['headphones','Audio'],['video','Video'],['book-open','Books & PDFs']].map(([i,t])=>`<article><span class="fasting-card-icon"><i class="ph ph-${i}"></i></span><h3>${t}</h3><p>Verified resources will appear here during the content phase.</p><span class="status-pill">0 resources</span></article>`).join('')}</div></section>`}
function fastingSettings(){return `<section class="vision-page fasting-companion-page">${fastingBreadcrumb([{label:'Settings'}])}<header class="editorial-header"><p class="page-kicker">Module preferences</p><h2>Fasting Settings</h2><p>The settings route is established for future calendar, reminders, history, and privacy controls.</p></header><section class="settings-page-card"><div class="settings-row"><span><strong>Hijri calendar</strong><small>Choose calculation and adjustment preferences in a future version.</small></span><span class="status-pill">Planned</span></div><div class="settings-row"><span><strong>Timely fasting reminders</strong><small>Monday, Thursday, White Days, and seasonal fasting prompts.</small></span><span class="status-pill">Planned</span></div><div class="settings-row"><span><strong>History display</strong><small>Control which fast categories appear in summaries.</small></span><span class="status-pill">Planned</span></div></section></section>`}
function fastingDetail(parentRoute,parentLabel,title,description,icon='book-open-text'){return `<section class="vision-page fasting-companion-page">${fastingBreadcrumb([{label:parentLabel,route:parentRoute},{label:title}])}<article class="fasting-detail-shell"><span class="fasting-card-icon is-large"><i class="ph ph-${icon}"></i></span><p class="section-eyebrow">Framework established</p><h2>${esc(title)}</h2><p>${esc(description)}</p><div class="fasting-detail-slots"><div><i class="ph ph-book-open-text"></i><strong>Overview & virtues</strong><small>Sourced educational content will live here.</small></div><div><i class="ph ph-seal-check"></i><strong>Evidence</strong><small>Qur’an, authentic hadith, and scholarly references.</small></div><div><i class="ph ph-warning-circle"></i><strong>Important guidance</strong><small>Conditions, exceptions, and common questions.</small></div><div><i class="ph ph-books"></i><strong>Related resources</strong><small>Connected library items without duplication.</small></div></div><a class="button button-secondary" href="${parentRoute}" data-route><i class="ph ph-arrow-left"></i> Back to ${esc(parentLabel)}</a></article></section>`}
function fastingContent(path){const p=routeParts(path);if(path==='/fasting')return fastingHome();if(path==='/fasting/learn')return fastingLearn();if(p[1]==='learn'&&p[2]){const x=FASTING_LEARN[p[2]]||['Fasting Lesson','Future sourced lesson.','book-open-text'];return fastingDetail('/fasting/learn','Learn About Fasting',x[0],x[1],x[2]);}if(path==='/fasting/sunnah')return fastingSunnah();if(p[1]==='sunnah'&&p[2]){const x=SUNNAH_FASTS[p[2]]||['Sunnah Fast','Future sourced guide.','calendar-check'];return fastingDetail('/fasting/sunnah','Sunnah Fasts',x[0],x[1],x[2]);}if(path==='/fasting/history')return fastingHistory();if(path==='/fasting/makeup')return fastingMakeup();if(path==='/fasting/library')return fastingLibrary();if(path==='/fasting/settings')return fastingSettings();return fastingHome();}

function futureModulePlaceholder(active){
  const isPrayer=active.id==='prayer';
  const features=isPrayer
    ? [
        ['book-open-text','Prayer from beginning to end','A future guided resource covering preparation, movements, recitations, and completion of the prayer.'],
        ['books','Trusted study resources','Articles, lessons, and references will be gathered into one calm study library.'],
        ['clock','Prayer times','A future location-aware prayer-time area can live here without crowding the learning resources.']
      ]
    : [
        ['calendar-check','Year-round fasting record','A future place to record obligatory, make-up, and voluntary fasts beyond Ramadan.'],
        ['book-open-text','Authentic fasting guidance','Trusted resources about intentions, rulings, virtues, and common questions.'],
        ['archive','Fasting history','A clear long-term record while Ramadan-specific tracking remains in Ramadan Central.']
      ];
  return `<section class="vision-page future-module-placeholder"><header class="editorial-header"><p class="page-kicker">${esc(active.label)}</p><h2>${esc(active.bannerTitle)}</h2><p>${esc(active.description)}</p><span class="status-pill">Placeholder module</span></header><div class="vision-link-grid three">${features.map(([iconName,title,description])=>`<article class="future-module-feature">${visionIcon(iconName)}<span><strong>${esc(title)}</strong><small>${esc(description)}</small></span></article>`).join('')}</div><div class="placeholder-panel"><p>This module is registered in the global navigation and ready for its future blueprint. No tracking or live location services have been enabled yet.</p></div></section>`;
}

function placeholders(active){if(active.id==='home')return sidebarOrder.filter(id=>!['home','settings','prayer','fasting'].includes(id)).map(id=>{const x=modules[id];return `<article class="card"><span class="status-pill">Foundation registered</span><h2>${esc(x.label)}</h2><p>${esc(x.description)}</p><a href="${x.navigation[0].route}" data-route>Open ${esc(x.label)}</a></article>`}).join('');return `<article class="card"><span class="status-pill">v${APP_VERSION} foundation</span><h2>Module shell is ready</h2><p>This module remains a placeholder while Duaa receives its first complete collection and reading experience.</p></article>`}
function bannerMeta(active,path){
  if(path==='/quran/journeys'||path==='/quran/reading-units'||path==='/quran/surahs')return {eyebrow:'Qur’an',title:'Your Reading Journeys',description:'Continue your journey through the Qur’an with a reading path that remembers your progress and grows with you over time.'};
  const duaaBanners={
    '/duaa':{eyebrow:'DUAA',title:'Duaa Home',description:'Authentic supplications for every stage of your day.'},
    '/duaa/morning':{eyebrow:'DUAA',title:'Morning Duaas',description:'Begin your day with authentic remembrance.'},
    '/duaa/evening':{eyebrow:'DUAA',title:'Evening Duaas',description:'Close your day with authentic remembrance.'},
    '/duaa/sleep':{eyebrow:'DUAA',title:'Before Sleep Duaas',description:'End your day with remembrance, protection, and trust in Allah.'},
    '/duaa/travel':{eyebrow:'DUAA',title:'Travel Duaas',description:'Remember Allah as you set out, travel, stop, and return.'},
    '/duaa/weather':{eyebrow:'DUAA',title:'Weather Duaas',description:'Remember Allah through rain, wind, storms, and changing skies.'},
    '/duaa/prayer':{eyebrow:'DUAA',title:'Prayer Duaas',description:'Supplications connected to the masjid, prayer, and seeking guidance.'},
    '/duaa/collections':{eyebrow:'DUAA',title:'Collections',description:'Explore authentic supplications for every time and situation.'},
    '/duaa/memorization':{eyebrow:'DUAA',title:'My Duaa Memorization',description:'See every supplication you have memorized and what you are still learning.'},
    '/duaa/history':{eyebrow:'DUAA',title:'History',description:'Reflect on your journey of remembrance.'},
    '/duaa/food':{eyebrow:'DUAA',title:'Food & Drink Duaas',description:'Remember Allah before, during, and after eating and drinking.'},
    '/duaa/clothing':{eyebrow:'DUAA',title:'Clothing Duaas',description:'Remember Allah when dressing and receiving new clothing.'},
    '/duaa/anxiety':{eyebrow:'DUAA',title:'Anxiety & Sadness Duaas',description:'Turn to Allah through worry, grief, distress, and sadness.'},
    '/duaa/quranic':{eyebrow:'DUAA',title:'Qur’anic Duaas',description:'Supplications from the Qur’an, including the prayers of the prophets and the righteous.'}
  };
  if(active.id==='fasting'){const titles={learn:['Learn About Fasting','Foundations, rulings, exemptions, and practical guidance for the worship of fasting.'],sunnah:['Sunnah Fasts','Explore recurring and seasonal voluntary fasts.'],history:['Fasting History','See Ramadan, Sunnah, and make-up fasts in one lifelong record.'],makeup:['Make-up Fasts','Track missed Ramadan days and completed make-up fasts.'],library:['Fasting Library','Trusted resources for learning about fasting.'],settings:['Fasting Settings','Future calendar, reminder, history, and privacy controls.']};const key=routeParts(path)[1];const meta=titles[key];return {eyebrow:'FASTING COMPANION',title:meta?.[0]||active.bannerTitle,description:meta?.[1]||active.description};}
  if(active.id==='prayer'){const titles={'daily-prayers':['Five Daily Prayers','Study each obligatory prayer with clarity and structure.'],sunnah:['Sunnah & Voluntary Prayers','Explore the prayers that surround and enrich the obligatory prayers.'],learn:['Learn the Prayer','Move through the prayer from preparation to completion.'],wudu:['Wudu Companion','Learn purification as a guided foundation for prayer.'],duaa:['Prayer Duaa Library','Find supplications by their place within the prayer.'],knowledge:['Prayer Knowledge','Build sound understanding around the prayer.'],progress:['My Progress','See the learning path that will grow with you.'],calendar:['Prayer Calendar','A future home for prayer schedules.'],settings:['Prayer Settings','Future controls for accurate local prayer times.']};const key=routeParts(path)[1];const meta=titles[key];return {eyebrow:'PRAYER COMPANION',title:meta?.[0]||active.bannerTitle,description:meta?.[1]||active.description};}
  return duaaBanners[path]||{eyebrow:active.bannerEyebrow,title:active.bannerTitle,description:active.description};
}
function viewName(active,path){if(active.id==='fasting'){const p=routeParts(path);if(p.length>2)return (FASTING_LEARN[p[2]]?.[0]||SUNNAH_FASTS[p[2]]?.[0]||'Fasting Companion');}if(active.id==='names'){const p=routeParts(path);if(p[1]==='name'&&p[2])return nameById(p[2])?.transliteration||'Beautiful Name';}if(active.id==='prayer'){const p=routeParts(path);if(p.length>2)return (PRAYER_DAILY[p[2]]?.name||PRAYER_SUNNAH[p[2]]?.[0]||PRAYER_LESSONS[p[2]]?.[0]||PRAYER_WUDU[p[2]]?.[0]||PRAYER_KNOWLEDGE[p[2]]?.[0]||PRAYER_DUAA[p[2]]?.[0]||'Prayer Companion');}if(active.id==='duaa'){if(path==='/duaa/memorization')return'My Duaa Memorization';const p=routeParts(path),c=duaaCollections[p[1]];if(p[2]==='read')return c?.label||'Reading';if(c)return c.label;if(path==='/duaa/collections')return'Collections';if(path==='/duaa/history')return'History';}if(active.id==='quran'){if(path==='/quran/journeys'||path==='/quran/reading-units'||path==='/quran/surahs')return'Reading Journeys';if(path.includes('/reading-unit/'))return'Reading Unit';if(path.includes('/classic/'))return'Classic Journey';if(path.includes('/featured-readings/'))return'Featured Reading';if(path.includes('/navigator'))return'Qur’an Navigator';}if(active.id==='ramadan'&&path==='/ramadan/reading')return'Ramadan Reading Journey';return active.navigation.find(x=>x.route===path)?.label||active.navigation[0].label}
function accountName(identity,user){return identity?.fullName||user?.user_metadata?.full_name||user?.user_metadata?.name||user?.email?.split('@')[0]||'My Account'}
function accountInitials(name,email){const source=String(name||email||'U').trim();const words=source.split(/\s+/).filter(Boolean);return esc((words.length>1?`${words[0][0]}${words.at(-1)[0]}`:source.slice(0,2)).toUpperCase())}
function formatAccountDate(value){if(!value)return 'Not available';const date=new Date(value);return Number.isNaN(date.getTime())?'Not available':date.toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}
function accountControls(user,identity,configured){
  const isAuthenticated=Boolean(user);
  const name=isAuthenticated?accountName(identity,user):"Preview Mode";
  const email=isAuthenticated?(identity?.email||user?.email||""):"Supabase is not configured";
  const initials=isAuthenticated?accountInitials(name,email):"LP";
  const sessionAction=isAuthenticated
    ? `<div class="account-menu-divider"></div><button class="account-sign-out" type="button" role="menuitem" data-request-sign-out><i class="ph ph-sign-out" aria-hidden="true"></i><span>Sign Out</span></button>`
    : `<p class="account-preview-note"><i class="ph ph-info" aria-hidden="true"></i><span>Account details and Sign Out become active when the app is connected to Supabase.</span></p>`;
  const profileDetails=isAuthenticated
    ? `<dl class="account-details"><div><dt>Display name</dt><dd>${esc(name)}</dd></div><div><dt>Email</dt><dd>${esc(email)}</dd></div><div><dt>Account created</dt><dd>${esc(formatAccountDate(user?.created_at))}</dd></div><div><dt>Last sign in</dt><dd>${esc(formatAccountDate(user?.last_sign_in_at))}</dd></div></dl><p class="dialog-note">Profile editing will be added when account settings are expanded.</p>`
    : `<div class="account-empty-state"><i class="ph ph-user-circle" aria-hidden="true"></i><h3>Preview Mode</h3><p>Supabase is not configured. The account controls remain visible so the application shell can be reviewed locally.</p></div>`;
  return `<div class="account-control"><button class="profile-button" type="button" data-profile-button aria-haspopup="menu" aria-expanded="false" aria-controls="account-menu"><span class="profile-avatar" aria-hidden="true">${initials}</span><span class="sr-only">Open account menu</span><i class="ph ph-caret-down" aria-hidden="true"></i></button><div class="account-menu" id="account-menu" role="menu" data-account-menu hidden><div class="account-summary"><span class="profile-avatar is-large" aria-hidden="true">${initials}</span><div><strong>${esc(name)}</strong><span>${esc(email)}</span></div></div><div class="account-menu-divider"></div><button type="button" role="menuitem" data-open-account-dialog="profile-dialog"><i class="ph ph-user-circle" aria-hidden="true"></i><span>My Profile</span></button><button type="button" role="menuitem" data-open-account-dialog="preferences-dialog"><i class="ph ph-sliders-horizontal" aria-hidden="true"></i><span>Preferences</span></button><button type="button" role="menuitem" data-open-account-dialog="about-dialog"><i class="ph ph-info" aria-hidden="true"></i><span>About Ummiby Companion</span></button>${sessionAction}</div></div><dialog class="account-dialog" id="profile-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Account</p><h2>My Profile</h2></div><button class="dialog-close" value="cancel" aria-label="Close profile"><i class="ph ph-x" aria-hidden="true"></i></button></div>${profileDetails}</form></dialog><dialog class="account-dialog" id="preferences-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Account</p><h2>Preferences</h2></div><button class="dialog-close" value="cancel" aria-label="Close preferences"><i class="ph ph-x" aria-hidden="true"></i></button></div><div class="account-empty-state"><i class="ph ph-sliders-horizontal" aria-hidden="true"></i><h3>Your preferences will live here</h3><p>The account-preferences service is connected and ready for future user-controlled settings.</p></div></form></dialog><dialog class="account-dialog" id="about-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Application</p><h2>About Ummiby Companion</h2></div><button class="dialog-close" value="cancel" aria-label="Close about"><i class="ph ph-x" aria-hidden="true"></i></button></div><div class="about-mark" aria-hidden="true">U</div><dl class="account-details"><div><dt>Version</dt><dd>v${APP_VERSION}</dd></div><div><dt>Account connection</dt><dd>${configured?'Connected':'Preview mode'}</dd></div></dl></form></dialog>${isAuthenticated?`<dialog class="account-dialog is-confirmation" id="sign-out-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Account</p><h2>Sign out?</h2></div><button class="dialog-close" value="cancel" aria-label="Cancel sign out"><i class="ph ph-x" aria-hidden="true"></i></button></div><p>You’ll return to the login screen. Your saved account data will remain available the next time you sign in.</p><div class="dialog-actions"><button class="button button-secondary" value="cancel">Cancel</button><button class="button button-danger" type="button" data-confirm-sign-out>Sign Out</button></div></form></dialog>`:''}`;
}

export function renderShell({pathname='/home',user=null,identity=null,configured=false,historyView=null}={}){const active=moduleForPath(pathname),view=viewName(active,pathname),reader=isReader(pathname),banner=bannerMeta(active,pathname);document.documentElement.dataset.theme=active.theme;document.title=`${view} | Ummiby Companion`;return `<div class="app-shell${reader?' is-reading':''}"><header class="brand-panel"><div class="brand-lockup"><div class="brand-mark" aria-hidden="true">U</div><p class="brand-name">Ummiby<br>Companion</p><p class="brand-version">v${APP_VERSION}</p></div></header><section class="module-banner${active.id==='prayer'?' is-prayer-banner':''}${active.id==='names'?' is-names-banner':''}${pathname==='/quran'?' is-quran-home-banner':''}${['/quran/journeys','/quran/reading-units','/quran/surahs'].includes(pathname)?' is-quran-journeys-banner':''}${pathname==='/duaa'?' is-duaa-home-banner':''}${pathname==='/duaa/morning'?' is-duaa-morning-banner':''}${pathname==='/duaa/evening'?' is-duaa-evening-banner':''}${pathname==='/duaa/sleep'?' is-duaa-sleep-banner':''}${pathname==='/duaa/travel'?' is-duaa-travel-banner':''}${pathname==='/duaa/weather'?' is-duaa-weather-banner':''}${pathname==='/duaa/prayer'?' is-duaa-prayer-banner':''}${pathname==='/duaa/collections'?' is-duaa-collections-banner':''}${pathname==='/duaa/history'?' is-duaa-history-banner':''}${pathname==='/duaa/food'?' is-duaa-food-banner':''}${pathname==='/duaa/clothing'?' is-duaa-clothing-banner':''}${pathname==='/duaa/anxiety'?' is-duaa-anxiety-banner':''}${pathname==='/duaa/quranic'?' is-duaa-quranic-banner':''}"><div class="banner-copy"><p class="banner-eyebrow">${esc(banner.eyebrow)}</p><h1 class="banner-title">${esc(banner.title)}</h1><p class="banner-description">${esc(banner.description)}</p></div>${accountControls(user,identity,configured)}</section><aside class="app-sidebar">${sidebar(active)}</aside><main class="module-workspace">${reader?'':moduleNav(active,pathname)}<section class="module-content${active.id==='duaa'?' is-duaa-content':''}${reader?' is-reader-content':''}" id="module-content" tabindex="-1">${active.id==='duaa'?duaaContent(pathname,historyView):active.id==='quran'?quranContent(pathname):active.id==='ramadan'?ramadanContent(pathname):active.id==='prayer'?prayerContent(pathname):active.id==='names'?namesContent(pathname):active.id==='fasting'?fastingContent(pathname):`<header class="page-header"><p class="page-kicker">${esc(active.label)}</p><h2 class="page-title">${esc(view)}</h2><p class="page-description">${esc(active.description)}</p></header><div class="card-grid">${placeholders(active)}</div>`}</section></main></div>`}
